import { test } from 'node:test';
import assert from 'node:assert/strict';
import { atualizarItemPorId } from './solution.mjs';

test('atualiza o item certo e mantém os demais intactos', () => {
  const lista = [
    { id: 1, nome: 'estudar', feito: 0 },
    { id: 2, nome: 'treinar', feito: 1 },
  ];
  const resultado = atualizarItemPorId(lista, 1, { feito: 1 });
  assert.deepEqual(resultado, [
    { id: 1, nome: 'estudar', feito: 1 },
    { id: 2, nome: 'treinar', feito: 1 },
  ]);
});

test('faz update parcial: o que não foi passado permanece igual', () => {
  const lista = [{ id: 7, nome: 'estudar', feito: 0 }];
  const resultado = atualizarItemPorId(lista, 7, { nome: 'estudar Node' });
  assert.deepEqual(resultado, [{ id: 7, nome: 'estudar Node', feito: 0 }]);
});

test('lança erro quando o id não existe', () => {
  const lista = [{ id: 1, nome: 'estudar' }];
  assert.throws(() => atualizarItemPorId(lista, 99, { nome: 'x' }), /não encontrado/);
});

test('lança erro quando não há mudanças para aplicar', () => {
  const lista = [{ id: 1, nome: 'estudar' }];
  assert.throws(() => atualizarItemPorId(lista, 1, {}), /nada para atualizar/);
  assert.throws(() => atualizarItemPorId(lista, 1, undefined), /nada para atualizar/);
});

solutionCode:
// Atualizar um item pelo id: devolve uma lista nova com o item atualizado.
export function atualizarItemPorId(lista, id, mudancas) {
  // findIndex devolve a posição do item, ou -1 se ele não existir
  const indice = lista.findIndex((item) => item.id === id);
  if (indice === -1) {
    throw new Error(`item ${id} não encontrado`);
  }
  // sem mudanças não há o que fazer — evita update "vazio"
  if (!mudancas || Object.keys(mudancas).length === 0) {
    throw new Error('nada para atualizar');
  }
  // espalha o item atual e aplica as mudanças por cima
  const atualizado = { ...lista[indice], ...mudancas };
  // monta a lista nova: antes do item + item atualizado + depois do item
  return [...lista.slice(0, indice), atualizado, ...lista.slice(indice + 1)];
}
